// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address caller, address newOwner, address querier) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        vm.prank(caller);
        c.transferOwnership(newOwner);
        vm.prank(querier);
        assertTrue(c.owner() == newOwner, "owner() must return the transferred owner regardless of caller");
    }
}

