pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        c.initialize();
        // owner is address(this) (deployer) via __Ownable_init_unchained

        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // General rule: transferring ownership to any non-zero address always succeeds.
        assertTrue(ok);
    }
}

