// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(0xA11CE);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        // No narrowing on newImpl: the zero address is admissible and is exactly
        // the input that separates P from M.
        bool ok;
        vm.prank(owner);
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever updateRoundImplementation succeeds,
        // the stored round implementation is not the zero address.
        assertTrue(!ok || c.roundImplementation() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address actor, address newImpl) public {
        vm.assume(actor != address(0));
        vm.assume(newImpl != address(0));

        vm.prank(actor);
        try c.updateRoundImplementation(payable(newImpl)) {
            // call succeeded; the storage must now hold the requested value
            assertTrue(c.roundImplementation() == newImpl);
        } catch {
            // call reverted; since owner is address(this), only the non-owner path reverts here
            assertTrue(actor != c.owner() && c.roundImplementation() != newImpl);
        }
    }
}
